198	export const attachmentServiceClient = createClient(AttachmentService, transport);
199	export const aiServiceClient = createClient(AIService, transport);
200	export const shortcutServiceClient = createClient(ShortcutService, transport);
201	
202	// Configuration service clients
203	export const identityProviderServiceClient = createClient(IdentityProviderService, transport);
