1	const STATE_STORAGE_KEY = "oauth_state";
2	const STATE_EXPIRY_MS = 10 * 60 * 1000; // 10 minutes
3	
4	export type OAuthFlowMode = "signin" | "link";
5	
6	interface OAuthState {
7	  state: string;
8	  identityProviderName: string;
9	  flowMode: OAuthFlowMode;
10	  timestamp: number;
11	  returnUrl?: string;
12	  linkingUserName?: string;
13	  codeVerifier?: string; // PKCE code_verifier
14	}
15	
16	// Generate a cryptographically secure random state value
17	function generateSecureState(): string {
18	  const array = new Uint8Array(32);
19	  crypto.getRandomValues(array);
20	  return Array.from(array, (byte) => byte.toString(16).padStart(2, "0")).join("");
21	}
22	
23	// Generate a cryptographically secure random code_verifier for PKCE (RFC 7636)
24	// Returns a URL-safe base64 string (43-128 characters)
25	function generateCodeVerifier(): string {
26	  const array = new Uint8Array(32); // 256 bits = 32 bytes
27	  crypto.getRandomValues(array);
28	  // Convert to base64url (URL-safe base64 without padding)
29	  return base64UrlEncode(array);
30	}
31	
32	// Generate code_challenge from code_verifier using SHA-256
33	async function generateCodeChallenge(codeVerifier: string): Promise<string> {
34	  const encoder = new TextEncoder();
35	  const data = encoder.encode(codeVerifier);
36	  const hash = await crypto.subtle.digest("SHA-256", data);
37	  return base64UrlEncode(new Uint8Array(hash));
38	}
39	
40	// Base64URL encoding (RFC 4648 base64url without padding)
41	function base64UrlEncode(buffer: Uint8Array): string {
42	  const base64 = btoa(String.fromCharCode(...buffer));
43	  return base64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
44	}
45	
46	// Store OAuth state and PKCE parameters in sessionStorage
47	// Returns state and optional codeChallenge for use in authorization URL
48	// PKCE is optional - if crypto APIs are unavailable (HTTP context), falls back to standard OAuth
49	export async function storeOAuthState(
50	  identityProviderName: string,
51	  flowMode: OAuthFlowMode,
52	  returnUrl?: string,
53	  linkingUserName?: string,
54	): Promise<{ state: string; codeChallenge?: string }> {
55	  const state = generateSecureState();
56	
57	  // Try to generate PKCE parameters if crypto.subtle is available (HTTPS/localhost)
58	  // Falls back to standard OAuth flow if unavailable (HTTP context)
59	  let codeVerifier: string | undefined;
60	  let codeChallenge: string | undefined;
61	
62	  try {
63	    // Check if crypto.subtle is available (requires secure context: HTTPS or localhost)
64	    if (typeof crypto !== "undefined" && crypto.subtle) {
65	      codeVerifier = generateCodeVerifier();
66	      codeChallenge = await generateCodeChallenge(codeVerifier);
67	    } else {
68	      console.warn(
69	        "PKCE not available: crypto.subtle requires HTTPS. Falling back to standard OAuth flow without PKCE. " +
70	          "For enhanced security, please access Memos over HTTPS.",
71	      );
72	    }
73	  } catch (error) {
74	    // If PKCE generation fails for any reason, fall back to standard OAuth
75	    console.warn("Failed to generate PKCE parameters, falling back to standard OAuth:", error);
76	    codeVerifier = undefined;
77	    codeChallenge = undefined;
78	  }
79	
80	  const stateData: OAuthState = {
81	    state,
82	    identityProviderName,
83	    flowMode,
84	    timestamp: Date.now(),
85	    returnUrl,
86	    linkingUserName,
87	    codeVerifier, // Store for later retrieval in callback (undefined if PKCE not available)
88	  };
89	
90	  try {
91	    sessionStorage.setItem(STATE_STORAGE_KEY, JSON.stringify(stateData));
92	  } catch (error) {
93	    console.error("Failed to store OAuth state:", error);
94	    throw new Error("Failed to initialize OAuth flow");
95	  }
96	
97	  return { state, codeChallenge };
98	}
99	
100	// Validate and retrieve OAuth state from storage (CSRF protection)
101	// Returns identityProviderName, flowMode, returnUrl, linkingUserName, and codeVerifier for PKCE
102	export function validateOAuthState(
103	  stateParam: string,
104	): { identityProviderName: string; flowMode: OAuthFlowMode; returnUrl?: string; linkingUserName?: string; codeVerifier?: string } | null {
105	  try {
106	    const storedData = sessionStorage.getItem(STATE_STORAGE_KEY);
107	    if (!storedData) {
108	      console.error("No OAuth state found in storage");
109	      return null;
110	    }
111	
112	    const stateData: OAuthState = JSON.parse(storedData);
113	
114	    // Check if state has expired
115	    if (Date.now() - stateData.timestamp > STATE_EXPIRY_MS) {
116	      console.error("OAuth state has expired");
117	      sessionStorage.removeItem(STATE_STORAGE_KEY);
118	      return null;
119	    }
120	
121	    // Validate state matches (CSRF protection)
122	    if (stateData.state !== stateParam) {
123	      console.error("OAuth state mismatch - possible CSRF attack");
124	      sessionStorage.removeItem(STATE_STORAGE_KEY);
125	      return null;
126	    }
127	
128	    // State is valid, clean up and return data
129	    sessionStorage.removeItem(STATE_STORAGE_KEY);
130	    return {
131	      identityProviderName: stateData.identityProviderName,
132	      flowMode: stateData.flowMode || "signin",
133	      returnUrl: stateData.returnUrl,
134	      linkingUserName: stateData.linkingUserName,
135	      codeVerifier: stateData.codeVerifier, // Return PKCE code_verifier
136	    };
137	  } catch (error) {
138	    console.error("Failed to validate OAuth state:", error);
139	    sessionStorage.removeItem(STATE_STORAGE_KEY);
140	    return null;
141	  }
142	}
143	
144	// Clean up expired OAuth states (call on app init)
145	export function cleanupExpiredOAuthState(): void {
146	  try {
147	    const storedData = sessionStorage.getItem(STATE_STORAGE_KEY);
148	    if (!storedData) {
149	      return;
150	    }
151	
152	    const stateData: OAuthState = JSON.parse(storedData);
153	    if (Date.now() - stateData.timestamp > STATE_EXPIRY_MS) {
154	      sessionStorage.removeItem(STATE_STORAGE_KEY);
155	    }
156	  } catch {
157	    // If parsing fails, remove the corrupted data
158	    sessionStorage.removeItem(STATE_STORAGE_KEY);
159	  }
160	}
